import 'package:flutter/material.dart';
import '../../core/api/aaspass_api.dart';
import '../../core/theme/app_theme.dart';

class HelpScreen extends StatelessWidget{const HelpScreen({super.key});Future<void> _ticket(BuildContext context)async{final subject=TextEditingController(),message=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(_)=>AlertDialog(title:const Text('Contact AasPass Support',style:TextStyle(fontWeight:FontWeight.w900)),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:subject,decoration:const InputDecoration(labelText:'Subject')),const SizedBox(height:10),TextField(controller:message,maxLines:4,decoration:const InputDecoration(labelText:'What happened?'))]),actions:[TextButton(onPressed:()=>Navigator.pop(context,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(context,true),child:const Text('Send'))]));if(ok==true){try{await AasPassApi.instance.post('/support',{'subject':subject.text.trim(),'description':message.text.trim(),'priority':'NORMAL'});if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Support ticket created.')));}catch(e){if(context.mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('Could not create support ticket: $e')));}}subject.dispose();message.dispose();}
@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Help & support',style:TextStyle(fontWeight:FontWeight.w900))),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('How can we help?',style:TextStyle(fontSize:22,fontWeight:FontWeight.w900)),const SizedBox(height:12),const _Question(title:'Where is my order?',body:'Open Orders to see the latest delivery status and tracking.'),const _Question(title:'Something is missing',body:'Open support and raise a ticket with your order details.'),const _Question(title:'Payment issue',body:'Keep your order ID ready; support can inspect the payment timeline.'),const SizedBox(height:8),FilledButton.icon(onPressed:()=>_ticket(context),icon:const Icon(Icons.support_agent_rounded),label:const Text('Contact support'))]));}
class _Question extends StatelessWidget{const _Question({required this.title,required this.body});final String title,body;@override Widget build(BuildContext c)=>Card(margin:const EdgeInsets.only(bottom:10),child:ExpansionTile(title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),children:[Padding(padding:const EdgeInsets.fromLTRB(16,0,16,16),child:Text(body))]));}
